import java.util.ArrayList;

public class WrapperPractice {
    public static int sumEvenNumbers(ArrayList<Integer> numbers) {
        int sum = 0;
        for (Integer num : numbers) {
            if (num != null && num % 2 == 0) {
                sum += num;
            }
        }
        return sum;
    }
}
